from drf_spectacular.utils import (
    extend_schema, OpenApiParameter, OpenApiTypes, OpenApiExample, OpenApiResponse,
)


class BookViewSet(viewsets.ModelViewSet):
    queryset = Book.objects.all()
    serializer_class = BookSerializer

    @extend_schema(
        summary="لیست کتاب‌ها",
        description="لیست کتاب‌های فعال با فیلتر و جستجو.",
        parameters=[
            OpenApiParameter("category", OpenApiTypes.STR, description="اسلاگ دسته‌بندی"),
            OpenApiParameter("min_price", OpenApiTypes.DECIMAL, description="حداقل قیمت"),
            OpenApiParameter("search", OpenApiTypes.STR, description="جستجو در عنوان"),
        ],
        responses={200: BookListSerializer(many=True)},
        examples=[
            OpenApiExample(
                "نمونه پاسخ",
                value={"id": 1, "title": "Clean Code", "price": "42.50"},
                response_only=True,
            ),
        ],
    )
    def list(self, request, *args, **kwargs):
        return super().list(request, *args, **kwargs)

    @extend_schema(
        summary="ساخت کتاب",
        responses={
            201: BookSerializer,
            400: OpenApiResponse(description="داده نامعتبر"),
        },
    )
    def create(self, request, *args, **kwargs):
        return super().create(request, *args, **kwargs)

