)


class ProductViewSet(viewsets.ModelViewSet):
    queryset = Product.objects.all()
    serializer_class = ProductSerializer

    @extend_schema(
        summary="لیست محصولات",
        description="محصولات فعال با فیلتر دسته، برند و بازه قیمت.",
        parameters=[
            OpenApiParameter("category", OpenApiTypes.STR),
            OpenApiParameter("brand", OpenApiTypes.STR),
            OpenApiParameter("min_price", OpenApiTypes.DECIMAL),
            OpenApiParameter("max_price", OpenApiTypes.DECIMAL),
        ],
        examples=[
            OpenApiExample("نمونه", value={"id": 1, "name": "Keyboard", "price": "89.50"}, response_only=True),
        ],
    )
    def list(self, request, *args, **kwargs):
        return super().list(request, *args, **kwargs)

    @extend_schema(
        responses={
            201: ProductSerializer,
            400: OpenApiResponse(description="داده نامعتبر"),
        },
    )
    def create(self, request, *args, **kwargs):
        return super().create(request, *args, **kwargs)
